package glitch

import data.glitch_lib

hardcoded_keywords := {"password", "pass", "pwd", "secret", "credential", "auth", "key", "token", "apikey", "private_key", "certificate", "ssh_key", "auth_token"}

is_hardcoded_string(value) {
    value.ir_type == "String"
    value.value != ""
    not startswith(value.value, "$")
    not startswith(value.value, "{{")
    not startswith(value.value, "var.")
    not startswith(value.value, "env.")
}

# Check if the key name suggests a credential
is_credential_key(name) {
    regex.match(sprintf("(?i).*(%s).*", [concat("|", hardcoded_keywords)]), name)
}

# Recursive helper to find hardcoded strings within complex values
find_hardcoded_in_value(value, path) = hits {
    value.ir_type == "String"
    is_hardcoded_string(value)
    hits := [{"value": value, "path": path}]
} else = hits {
    value.ir_type == "Hash"
    hits := {h |
        some kv in value.value
        h := find_hardcoded_in_value(kv.value, path + [kv.key.value])
    }
} else = hits {
    value.ir_type == "Array"
    hits := {h |
        some v in value.value
        h := find_hardcoded_in_value(v, path)
    }
} else = hits {
    hits := set()
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Variables (e.g., Chef attributes)
    var := parent.variables[_]
    is_credential_key(var.name)
    is_hardcoded_string(var.value)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding sensitive authentication data directly in source code. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Attributes (e.g., Ansible variables)
    # In the IR, Ansible variables are often represented as UnitBlock.variables
    var := parent.variables[_]
    var.value.ir_type == "Hash"

    # Traverse the hash to find nested credential keys with hardcoded values
    hits := find_hardcoded_in_value(var.value, [var.name])
    count(hits) > 0
    hit := hits[_]

    # Build a synthetic element for the result to point to the specific line/column
    # We use the value of the hardcoded string itself
    element := {
        "ir_type": "Attribute",
        "line": hit.value.line,
        "column": hit.value.column,
        "end_line": hit.value.end_line,
        "end_column": hit.value.end_column,
        "code": hit.value.code,
        "name": hit.path[count(hit.path) - 1],
        "value": hit.value
    }

    result := {
        "type": "sec_hard_secr",
        "element": element,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding sensitive authentication data directly in source code. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Atomic Units (e.g., Puppet resources, Ansible tasks)
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_credential_key(attr.name)
    is_hardcoded_string(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding sensitive authentication data directly in source code. (CWE-798)"
    }
}

